class Solution:
    def minimumCost(self, n: int, highways: list[list[int]], discounts: int) -> int:
        adj = [[] for _ in range(n)]
        for u, v, toll in highways:
            adj[u].append((v, toll))
            adj[v].append((u, toll))

        dist = [[float('inf')] * (discounts + 1) for _ in range(n)]
        dist[0][0] = 0
        heap = [(0, 0, 0)]

        while heap:
