            if cost > dist[u][d]:
                continue
            if u == n - 1:
                return cost

            for v, toll in adj[u]:
                if cost + toll < dist[v][d]:
                    dist[v][d] = cost + toll
                    heapq.heappush(heap, (dist[v][d], v, d))

                if d < discounts and cost + toll // 2 < dist[v][d + 1]:
                    dist[v][d + 1] = cost + toll // 2
                    heapq.heappush(heap, (dist[v][d + 1], v, d + 1))

