#include <vector>
#include <queue>
#include <tuple>

class Solution {
public:
    int minimumCost(int n, std::vector<std::vector<int>>& highways, int discounts) {
        std::vector<std::vector<std::pair<int, int>>> adj(n);
        for (const auto& h : highways) {
            adj[h[0]].push_back({h[1], h[2]});
            adj[h[1]].push_back({h[0], h[2]});
        }

        std::vector<std::vector<int>> dist(n, std::vector<int>(discounts + 1, 1e9));
        dist[0][0] = 0;

        using State = std::tuple<int, int, int>;
        std::priority_queue<State, std::vector<State>, std::greater<State>> pq;
        pq.push({0, 0, 0});

        while (!pq.empty()) {
            auto [cost, u, d] = pq.top();
            pq.pop();

            if (cost > dist[u][d]) continue;
            if (u == n - 1) return cost;

            for (const auto& [v, toll] : adj[u]) {
                if (cost + toll < dist[v][d]) {
                    dist[v][d] = cost + toll;
                    pq.push({dist[v][d], v, d});
                }
                if (d < discounts && cost + toll / 2 < dist[v][d + 1]) {
                    dist[v][d + 1] = cost + toll / 2;
                    pq.push({dist[v][d + 1], v, d + 1});
                }
            }
        }
        return -1;
    }
};

import java.util.*;

class Solution {
    public int minimumCost(int n, int[][] highways, int discounts) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] h : highways) {
            adj.get(h[0]).add(new int[]{h[1], h[2]});
            adj.get(h[1]).add(new int[]{h[0], h[2]});
        }

        int[][] dist = new int[n][discounts + 1];
        for (int[] row : dist) Arrays.fill(row, Integer.MAX_VALUE);
        dist[0][0] = 0;

        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        pq.offer(new int[]{0, 0, 0});

        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int cost = top[0], u = top[1], d = top[2];

            if (cost > dist[u][d]) continue;
            if (u == n - 1) return cost;

            for (int[] edge : adj.get(u)) {
                int v = edge[0], toll = edge[1];
                if (cost + toll < dist[v][d]) {
                    dist[v][d] = cost + toll;
                    pq.offer(new int[]{dist[v][d], v, d});
                }
                if (d < discounts && cost + toll / 2 < dist[v][d + 1]) {
                    dist[v][d + 1] = cost + toll / 2;
                    pq.offer(new int[]{dist[v][d + 1], v, d + 1});
                }
            }
        }
        return -1;
    }
}

