var minimumCost = function(n, highways, discounts) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v, toll] of highways) {
        adj[u].push([v, toll]);
        adj[v].push([u, toll]);
    }

    const dist = Array.from({ length: n }, () => new Array(discounts + 1).fill(Infinity));
    dist[0][0] = 0;

    // Simple priority queue using sorted insertion
    const pq = [[0, 0, 0]];

    while (pq.length > 0) {
        // Pop lowest cost
        let minIdx = 0;
        for (let i = 1; i < pq.length; i++) {
            if (pq[i][0] < pq[minIdx][0]) minIdx = i;
        }
        const [cost, u, d] = pq.splice(minIdx, 1)[0];

        if (cost > dist[u][d]) continue;
        if (u === n - 1) return cost;

        for (const [v, toll] of adj[u]) {
            if (cost + toll < dist[v][d]) {
                dist[v][d] = cost + toll;
                pq.push([dist[v][d], v, d]);
            }
            if (d < discounts && cost + Math.floor(toll / 2) < dist[v][d + 1]) {
                dist[v][d + 1] = cost + Math.floor(toll / 2);
                pq.push([dist[v][d + 1], v, d + 1]);
            }
        }
    }
    return -1;
};
